某文件系统用**位示图**管理空闲盘块，字长 32 位，**盘块号从 1 开始编号**。下面的函数本应「由盘块号求字号与位号」，但存在错误（编号起点处理不对）。请指出错误并给出修复后的完整代码。

```c
void bitmap_addr(int block_no, int *word, int *bit) {
    *word = block_no / 32;
    *bit  = block_no % 32;
}
```

answer.code:
#include <stdio.h>

#define WORD_BITS 32
#define BASE 1        /* 盘块号从 1 开始；若题目说从 0 开始就把这里改成 0 */

void bitmap_addr(int block_no, int *word, int *bit) {
    int idx = block_no - BASE;      /* 关键：先归一到 0 基 */
    *word = idx / WORD_BITS;
    *bit  = idx % WORD_BITS;
}

int bitmap_block(int word, int bit) {
    return word * WORD_BITS + bit + BASE;
}

int main(void) {
    for (int b = 1; b <= 33; b += 16) {
        int w, o;
        bitmap_addr(b, &w, &o);
        printf("block %2d -> word=%d bit=%2d -> block %d (round trip ok: %s)\n",
               b, w, o, bitmap_block(w, o), bitmap_block(w, o) == b ? "true" : "false");
    }
    printf("if numbering started at 0: block 1 -> word=0 bit=1\n");
    return 0;
}

#include <stdio.h>

int lru_faults(const int *pages, int n, int capacity) {
    int frame[64], last[64], used = 0, faults = 0;
    for (int i = 0; i < n; i++) {
        int hit = -1;
        for (int j = 0; j < used; j++) if (frame[j] == pages[i]) { hit = j; break; }
        if (hit >= 0) { last[hit] = i; continue; }      /* 命中：只刷新时间戳 */
        faults++;
        if (used < capacity) { frame[used] = pages[i]; last[used] = i; used++; }
        else {
            int victim = 0;
            for (int j = 1; j < capacity; j++) if (last[j] < last[victim]) victim = j;
            frame[victim] = pages[i]; last[victim] = i;
        }
    }
    return faults;
}

int main(void) {
    int pages[] = {7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1};
    int n = 20;
    for (int cap = 3; cap <= 5; cap++)
        printf("capacity=%d -> faults=%d\n", cap, lru_faults(pages, n, cap));
    return 0;
}
